class Hospital {}

class Office {}

class User {}

class Doctor extends User {}

class Patient extends User {}

class Schedule {
  + Date : date
  + StartTime : time
  + EndTime : time
}

class Appointment {
  + DateTime : datetime
  + Duration : int
}

enum AppointmentType {
  BloodTest
  Consultation
  Surgery
}

Hospital "1" -- "*" Office
Doctor "1" -- "*" Schedule : creates
Office "1" -- "*" Schedule
Doctor "1" -- "*" Appointment : is provider for
Patient "1" -- "*" Appointment : books
Schedule "1" -- "1" Appointment : is for
Appointment "*" -- "1" AppointmentType

@enduml

